<template>
  <div class="page-wrap inventory-page">
    <PageHeader eyebrow="" title="数据资产" description="实库结构、业务字典、依赖证据分别核对，不将登记参考当作业务确认">
      <a-button :loading="loading" :disabled="editorOpen" @click="refresh">刷新已发布快照</a-button>
    </PageHeader>
    <a-alert v-if="error" type="error" show-icon :message="error" description="请求失败时保留上次成功结果。完整目录需要发布快照及查看权限；原经营口径与分析仍可从下方进入。" class="section-gap" />
    <a-alert v-if="notice" type="success" :message="notice" closable @close="notice = ''" class="section-gap" />
    <div v-if="summary" class="inventory-summary"><span>对象 <b>{{ summary.objectCount }}</b></span><span>字段 <b>{{ summary.fieldCount }}</b></span><span>业务字典已维护 <b>{{ summary.dictionaryCount }}</b></span><span>依赖证据 <b>{{ summary.edgeEvidenceCount }}</b> / 唯一依赖 {{ summary.uniqueDependencyCount }}</span><small>当前账号可见范围 · 运行证据未采集</small></div>
    <a-tabs v-model:active-key="tab" @change="changeTab">
      <a-tab-pane key="objects" tab="资产目录"><div v-if="summary" class="inventory-layout">
        <aside class="library-tree"><h2>连接与库</h2><button :class="{chosen:!database}" @click="selectDatabase('')">全部对象 <b>{{ summary.objectCount }}</b></button><template v-for="source in sources" :key="source"><h3>{{ source }}</h3><button v-for="db in summary.databases.filter(row=>row.source===source)" :key="db.source+db.database" :class="{chosen:database===db.source+'/'+db.database}" @click="selectDatabase(db.source+'/'+db.database)">{{ db.database }} <b>{{ db.object_count }}</b></button></template><small>按实例隔离同名对象，未见库不代表不存在。</small></aside>
        <div class="inventory-main"><FilterPanel :instant="false" :show-reset="false" stacked><div class="inventory-filters" style="grid-column:1 / -1"><label>表名 / 注释 / 字典<a-input v-model:value="search" allow-clear placeholder="多个词同时匹配" @press-enter="queryObjects" /></label><label>分层候选<a-select v-model:value="layer" :options="layerOptions" style="width:140px" /></label><label>字典维护<a-select v-model:value="dictionaryFilter" :options="[{value:'',label:'全部'},{value:'maintained',label:'已有发布修订'},{value:'missing',label:'尚未维护'}]" style="width:145px" /></label><a-button type="primary" :loading="listLoading" @click="queryObjects">查询</a-button><a-button @click="resetQuery">重置</a-button></div></FilterPanel>
          <div class="section-title"><h2>对象目录</h2><small>{{ displayedScope }}：{{ total }} / 全快照 {{ summary.objectCount }} 个</small></div>
          <a-table :loading="listLoading" :data-source="objects" :columns="objectColumns" row-key="asset_id" size="small" :pagination="{current:page,pageSize:20,total,showSizeChanger:false,onChange:changePage}" :scroll="{x:1280,y:'min(60vh, 620px)'}"><template #bodyCell="{column,record}">
            <template v-if="column.key==='name'"><a-button type="link" class="object-link" @click="openDetail(record.asset_id)">{{ record.table }}</a-button><small>{{ record.source }}/{{ record.database }} · {{ record.object_type }}</small></template>
            <template v-else-if="column.key==='business'">{{ record.dictionary.values.businessUse || '待维护业务用途' }}<small>{{ record.dictionary.revision ? `字典修订 ${record.dictionary.revision}` : '不以表名或物理注释代替业务口径' }}</small></template>
            <template v-else-if="column.key==='physical'">{{ record.table_comment && record.table_comment!=='VIEW' ? record.table_comment : '源库未提供注释' }}</template>
            <template v-else-if="column.key==='layer'"><a-tag>{{ layerName(record.layer_candidate) }}</a-tag><small v-if="!['NOT_ASSIGNED','UNCLASSIFIED'].includes(record.layer_candidate)">名称推断，职责待核对</small></template>
            <template v-else-if="column.key==='gap'"><a-button type="link" @click="openDetail(record.asset_id,'gaps')">{{ record.gapCount ? `${record.gapCount}条缺口记录` : '已检查项未发现缺口' }}</a-button></template>
          </template></a-table>
        </div>
      </div></a-tab-pane>
      <a-tab-pane key="lineage" tab="血缘与影响"><section v-if="summary" class="inventory-panel">
        <div class="inventory-filters"><label>中心对象<a-select v-model:value="centerId" show-search :filter-option="false" :options="centerOptions" :loading="centerLoading" style="width:min(600px, 75vw)" @search="searchCenters" @change="loadLineage" placeholder="搜索并选择对象" /></label><label>证据范围<a-select v-model:value="scope" style="width:165px" :options="[{value:'definition',label:'定义 / 源码依赖'},{value:'runtime',label:'仅实际运行证据'}]" @change="loadLineage" /></label><a-button :loading="lineageLoading" :disabled="!centerId" @click="loadLineage">查询依赖</a-button></div>
        <a-alert type="info" show-icon message="两端对象命中仅证明结构存在，不能证明任务运行成功。外键在对象详情单列，不混入加工血缘。" /><a-alert v-if="lineageError" type="error" :message="lineageError" class="section-gap" />
        <a-spin :spinning="lineageLoading"><a-empty v-if="!centerId" description="请选择中心对象，无需加载全库关系网" /><a-alert v-else-if="scope==='runtime'" type="warning" message="运行证据尚未采集，不能据此判断无上下游或零影响。" class="section-gap" /><template v-else-if="lineage">
          <div class="dependency-board"><div><h3>直接上游</h3><button v-for="node in upstream" :key="node.key" :disabled="!node.id" @click="selectCenter(node.id,node.label)">{{ node.label }}<small>{{ node.id?'切换中心对象':'端点未解析 / 未命中' }}</small></button><p v-if="!upstream.length">当前证据未覆盖上游</p></div><div class="center-node"><small>左侧 → 中心 → 右侧</small><strong>{{ centerLabel }}</strong><a-button type="link" @click="openDetail(centerId)">查看对象详情</a-button><small>运行未验证</small></div><div><h3>直接下游</h3><button v-for="node in downstreamNodes" :key="node.key" :disabled="!node.id" @click="selectCenter(node.id,node.label)">{{ node.label }}<small>{{ node.id?'切换中心对象':'端点未解析 / 未命中' }}</small></button><p v-if="!downstreamNodes.length">当前证据未覆盖下游</p></div></div>
          <div class="section-title"><h2>潜在下游影响</h2><small>最多5跳 / 500个对象；{{ lineage.unresolvedFrontier }}条未解析前沿证据</small></div><a-alert v-if="lineage.truncated" type="warning" message="已到遍历边界，当前不是完整影响集合。" /><div class="impact-links"><button v-for="item in lineage.impacts" :key="item.asset_id" @click="selectCenter(item.asset_id,`${item.source}/${item.database}/${item.table}`)">第{{ item.depth }}跳 · {{ item.source }}/{{ item.database }}/{{ item.table }}</button><p v-if="!lineage.impacts.length">已解析范围内未找到可遍历下游，不代表已验证无影响。</p></div>
          <a-table :data-source="lineage.edges" :columns="edgeColumns" row-key="evidence_id" size="small" :pagination="{pageSize:8}" :scroll="{x:1280}"><template #bodyCell="{column,record}"><template v-if="column.key==='type'">{{ edgeNames[record.edge_type] || record.edge_type }}</template><template v-else-if="column.key==='state'"><a-tag :color="record.endpoint_status==='both_exist'?'blue':'orange'">{{ record.endpoint_status==='both_exist'?'两端对象命中':'端点待核对' }}</a-tag><small>运行未验证</small></template></template><template #expandedRowRender="{record}"><p>证据位置：{{ record.evidence }}</p><p>源码 / 定义 SHA-256：{{ record.sha256 || '未登记' }}</p></template></a-table>
        </template></a-spin>
      </section></a-tab-pane>
      <a-tab-pane key="gaps" tab="治理清单"><section v-if="summary" class="inventory-panel"><a-alert type="info" message="类别可能重叠，不能相加作为问题表数。补充业务字典不会自动修改源库注释或消除物理结构缺口。" /><div class="gap-buttons"><a-button :type="gapType===''?'primary':'default'" @click="chooseGap('')">全部缺口记录</a-button><a-button v-for="(label,key) in summary.gapLabels" :key="key" :type="gapType===key?'primary':'default'" @click="chooseGap(String(key))">{{ label }} {{ summary.gapCounts[key] || 0 }}</a-button></div><a-alert v-if="gapError" type="error" :message="gapError" /><a-table :loading="gapLoading" :data-source="gaps" :columns="gapColumns" row-key="gap_id" size="small" :pagination="{current:gapPage,total:gapTotal,pageSize:20,showSizeChanger:false,onChange:changeGapPage}" :scroll="{x:1100}"><template #bodyCell="{column,record}"><template v-if="column.key==='type'">{{ summary.gapLabels[record.gap] || record.gap }}</template><template v-else-if="column.key==='action'"><a-button type="link" :disabled="!record.canLocate" @click="openDetail(record.asset_id,'gaps')">{{ record.canLocate?'定位与核对':'端点引用待解析' }}</a-button></template></template></a-table></section></a-tab-pane>
      <a-tab-pane key="collections" tab="采集记录"><section v-if="summary" class="inventory-panel"><a-alert type="info" message="当前展示已发布成功快照。采集由部署人执行只读采集及发布脚本，页面刷新不扫描全库；实际调度与业务时效尚未核验。" /><p>目录发布版本 {{ summary.version.slice(0,12) }} · {{ formatDateTimeDisplay(summary.publishedAt) }}</p><a-table :data-source="summary.databases" :columns="collectionColumns" :pagination="false" :row-key="(row:{source:string;database:string})=>row.source+row.database" :scroll="{x:1000}"><template #bodyCell="{column,record}"><template v-if="column.key==='time'">{{ formatDateTimeDisplay(record.collected_at) }}</template><template v-else-if="column.key==='state'"><a-tag color="blue">结构已采集</a-tag><small>业务时效未验</small></template></template></a-table><p>SQL/Shell证据覆盖：{{ summary.coverage.parsed ?? '未登记' }}份完成受支持块解析，{{ summary.coverage.partialOrFailed ?? '未登记' }}份部分/失败，{{ summary.coverage.unsupported ?? '未登记' }}份无受支持块。不是全部动态Python加工与外部调度覆盖率。</p></section></a-tab-pane>
      <a-tab-pane key="business" tab="经营口径与分析"><BusinessAssets v-if="tab==='business'" /></a-tab-pane>
    </a-tabs>
    <a-drawer v-model:open="detailOpen" title="对象详情" :width="'min(1100px, calc(100vw - 32px))'" :destroy-on-close="true">
      <a-alert v-if="detailError" type="error" :message="detailError" /><a-spin :spinning="detailLoading"><template v-if="detail"><h2 class="detail-name">{{ detail.object.table }}</h2><p>{{ detail.object.source }}/{{ detail.object.database }} · 实例 {{ detail.object.instance_id }}</p><a-tabs v-model:active-key="detailTab">
        <a-tab-pane key="dictionary" tab="业务字典"><a-alert type="info" message="业务字典独立留版本，物理注释与源码登记参考不自动升级为已确认口径。" /><a-descriptions :column="2" bordered size="small" class="section-gap"><a-descriptions-item v-for="field in dictionaryFields" :key="field.key" :label="field.label">{{ detail.dictionaryState.published[field.key] || '待维护' }}</a-descriptions-item></a-descriptions><div class="section-title"><small>已发布修订 {{ detail.dictionaryState.publishedRevision }}；业务新鲜度待实际数据核验</small><a-button v-if="summary?.canManageDictionary" type="primary" @click="editDictionary">维护字典草稿</a-button></div><p v-if="detail.dictionaryState.draft">存在未发布草稿，尚未替代当前发布字典。</p><h3>物理表注释</h3><p>{{ detail.object.table_comment || '未提供' }}</p><template v-if="detail.object.registeredContext"><h3>既有项目登记参考</h3><p>{{ detail.object.registeredContext.purpose }}</p><p>{{ detail.object.registeredContext.grain }}</p><small>{{ detail.object.registeredContext.evidence }}</small></template></a-tab-pane>
        <a-tab-pane key="columns" tab="字段字典"><a-table :data-source="detail.columns" :columns="fieldColumns" row-key="name" size="small" :pagination="{pageSize:15}" :scroll="{x:1000}"><template #bodyCell="{column,record}"><template v-if="column.key==='comment'">{{ record.comment || '物理注释缺失，中文含义待核对' }}</template><template v-else-if="column.key==='nullable'">{{ record.nullable || '当前引擎未登记' }}</template><template v-else-if="column.key==='partition'">{{ record.is_partition==='1'?'分区字段':'普通字段' }}</template></template></a-table></a-tab-pane>
        <a-tab-pane key="keys" tab="声明键与索引"><a-alert type="info" message="外键是结构关联，不是加工血缘。声明键与索引不等于已确认业务唯一粒度或JOIN基数。" /><h3>声明键</h3><a-table :data-source="detail.keys" :columns="keyColumns" :row-key="(row:Record<string,string>)=>row.CONSTRAINT_NAME+row.ORDINAL_POSITION" size="small" :pagination="{pageSize:10}" :scroll="{x:1000}" /><h3>索引</h3><a-table :data-source="detail.indexes" :columns="indexColumns" :row-key="(row:Record<string,string>)=>row.INDEX_NAME+row.SEQ_IN_INDEX" size="small" :pagination="{pageSize:10}" :scroll="{x:800}" /></a-tab-pane>
        <a-tab-pane key="gaps" tab="治理缺口"><a-table :data-source="detail.gaps" :columns="gapColumns.slice(0,3)" row-key="gap_id" size="small" :pagination="{pageSize:10}" :scroll="{x:800}"><template #bodyCell="{column,record}"><template v-if="column.key==='type'">{{ summary?.gapLabels[record.gap] || record.gap }}</template></template></a-table><a-button v-if="summary?.canManageDictionary" @click="editDictionary">补充业务字典</a-button></a-tab-pane>
        <a-tab-pane key="history" tab="字典修订历史"><ACollapse><ACollapsePanel v-for="revision in detail.dictionaryState.history" :key="revision.revision" :header="`修订 ${revision.revision} · ${formatDateTimeDisplay(revision.updatedAt)}`"><a-descriptions :column="1"><a-descriptions-item v-for="field in dictionaryFields" :key="field.key" :label="field.label">{{ revision.values[field.key] || '未维护' }}</a-descriptions-item></a-descriptions></ACollapsePanel></ACollapse><a-empty v-if="!detail.dictionaryState.history.length" description="尚无发布修订" /></a-tab-pane>
      </a-tabs><a-button @click="fromDetailToLineage">查看上下游与潜在影响</a-button></template></a-spin>
    </a-drawer>
    <FormDialog v-model:open="editorOpen" title="维护业务字典" :busy="writeBusy" :dirty="editorDirty" :error="writeError" ok-text="保存草稿" @submit="saveDictionary"><a-alert type="info" message="保存草稿不改变实库或已发布字典。请对照当前发布值，核对后再单独发布已保存草稿。" /><FormGrid><label v-for="field in dictionaryFields" :key="field.key" class="dictionary-field">{{ field.label }}<a-textarea v-model:value="editor[field.key]" :rows="2" :maxlength="field.limit" /></label></FormGrid><ACollapse><ACollapsePanel key="comparison" header="对照当前发布字典"><a-descriptions :column="1"><a-descriptions-item v-for="field in dictionaryFields" :key="field.key" :label="field.label">{{ detail?.dictionaryState.published[field.key] || '未维护' }}</a-descriptions-item></a-descriptions></ACollapsePanel></ACollapse><a-popconfirm title="将已保存草稿发布为新的业务字典修订？源库结构保持原样。" @confirm="publishDictionary"><a-button class="section-gap" :disabled="!detail?.dictionaryState.draftRevision || editorDirty || writeBusy">发布已保存草稿</a-button></a-popconfirm><small v-if="editorDirty">请先保存当前修改，再发布。</small></FormDialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { Collapse } from 'ant-design-vue'
import PageHeader from '@/components/PageHeader.vue'
import FilterPanel from '@/components/FilterPanel.vue'
import FormDialog from '@/components/FormDialog.vue'
import FormGrid from '@/components/FormGrid.vue'
import BusinessAssets from './BusinessAssets.vue'
import { inventoryApi } from '@/api/assetInventory'
import type { AssetDetail, AssetGap, AssetLineage, AssetObject, AssetSummary, Dictionary } from '@/api/assetInventory'
import { formatDateTimeDisplay } from '@/utils/dateTimeDisplay'
const ACollapse=Collapse, ACollapsePanel=Collapse.Panel
const tab=ref('objects'),summary=ref<AssetSummary>(),loading=ref(false),error=ref(''),notice=ref(''),objects=ref<AssetObject[]>([]),total=ref(0),page=ref(1),listLoading=ref(false)
const displayedScope=ref('尚未查询')
const database=ref(''),search=ref(''),layer=ref(''),dictionaryFilter=ref(''),applied=ref({search:'',layer:'',dictionaryState:''})
let listToken=0,detailToken=0,lineageToken=0,gapToken=0,centerToken=0,alive=true
const sources=computed(()=>[...new Set(summary.value?.databases.map(row=>row.source)??[])])
const layerName=(value:string)=>value==='NOT_ASSIGNED'?'非数仓分层':value==='UNCLASSIFIED'?'待分类':value
const layerOptions=[{value:'',label:'全部'},...['ODS','DWD','DWS','ADS','DIM','NOT_ASSIGNED','UNCLASSIFIED'].map(value=>({value,label:layerName(value)}))]
const fail=(reason:unknown)=>reason instanceof Error?reason.message:'请求失败，请刷新后重试'
async function loadObjects(){if(!summary.value)return;const token=++listToken;listLoading.value=true;error.value='';try{const next=await inventoryApi.objects({...applied.value,database:database.value,page:page.value,pageSize:20,version:summary.value.version});if(!alive||token!==listToken)return;if(page.value>Math.max(1,Math.ceil(next.total/20))){page.value=Math.max(1,Math.ceil(next.total/20));await loadObjects();return}objects.value=next.items;total.value=next.total;displayedScope.value=`已展示 ${database.value || '全部库'}${applied.value.search ? ' / '+applied.value.search : ''}${applied.value.layer ? ' / '+layerName(applied.value.layer) : ''}`}catch(reason){if(alive&&token===listToken)error.value=fail(reason)}finally{if(alive&&token===listToken)listLoading.value=false}}
async function refresh(){if(loading.value||editorOpen.value)return;loading.value=true;error.value='';try{const next=await inventoryApi.summary();if(!alive)return;const changed=summary.value?.version!==next.version;summary.value=next;if(changed){++detailToken;++lineageToken;++gapToken;++centerToken;detail.value=undefined;detailOpen.value=false;lineage.value=undefined;gaps.value=[];page.value=1;gapPage.value=1}await loadObjects();if(tab.value==='gaps')await loadGaps();if(tab.value==='lineage'&&centerId.value)await loadLineage()}catch(reason){if(alive)error.value=fail(reason)}finally{if(alive)loading.value=false}}
function queryObjects(){applied.value={search:search.value,layer:layer.value,dictionaryState:dictionaryFilter.value};page.value=1;void loadObjects()}
function resetQuery(){search.value='';layer.value='';dictionaryFilter.value='';database.value='';queryObjects()}
function selectDatabase(value:string){database.value=value;page.value=1;void loadObjects()}function changePage(value:number){page.value=value;void loadObjects()}
function changeTab(){if(tab.value==='gaps')void loadGaps();if(tab.value==='lineage'&&!centerOptions.value.length)void searchCenters('')}
const detailOpen=ref(false),detail=ref<AssetDetail>(),detailTab=ref('dictionary'),detailLoading=ref(false),detailError=ref('')
async function openDetail(id:string,section='dictionary'){if(!summary.value)return;const token=++detailToken;detailOpen.value=true;detail.value=undefined;detailError.value='';detailTab.value=section;detailLoading.value=true;try{const next=await inventoryApi.detail(id,summary.value.version);if(alive&&token===detailToken)detail.value=next}catch(reason){if(alive&&token===detailToken)detailError.value=fail(reason)}finally{if(alive&&token===detailToken)detailLoading.value=false}}
const centerId=ref(''),centerOptions=ref<{value:string;label:string}[]>([]),centerLoading=ref(false),scope=ref('definition'),lineage=ref<AssetLineage>(),lineageLoading=ref(false),lineageError=ref('')
const centerLabel=computed(()=>centerOptions.value.find(row=>row.value===centerId.value)?.label??centerId.value)
async function searchCenters(value:string){if(!summary.value)return;const token=++centerToken;centerLoading.value=true;try{const next=await inventoryApi.objects({search:value,page:1,pageSize:50,version:summary.value.version});if(!alive||token!==centerToken)return;const chosen=centerOptions.value.find(row=>row.value===centerId.value);centerOptions.value=next.items.map(row=>({value:row.asset_id,label:`${row.source}/${row.database}/${row.table}`}));if(chosen&&!centerOptions.value.some(row=>row.value===chosen.value))centerOptions.value.unshift(chosen)}catch(reason){if(alive&&token===centerToken)lineageError.value=fail(reason)}finally{if(alive&&token===centerToken)centerLoading.value=false}}
async function loadLineage(){if(!summary.value||!centerId.value)return;const token=++lineageToken;lineageLoading.value=true;lineageError.value='';lineage.value=undefined;try{const next=await inventoryApi.lineage(centerId.value,summary.value.version,scope.value);if(alive&&token===lineageToken)lineage.value=next}catch(reason){if(alive&&token===lineageToken)lineageError.value=fail(reason)}finally{if(alive&&token===lineageToken)lineageLoading.value=false}}
function selectCenter(id:string,label:string){if(!centerOptions.value.some(row=>row.value===id))centerOptions.value.push({value:id,label});centerId.value=id;void loadLineage()}
function neighbors(up:boolean){const result=new Map<string,{key:string;id:string;label:string}>();for(const row of lineage.value?.edges??[]){if((up?row.target_asset_id:row.source_asset_id)!==centerId.value)continue;const id=up?row.source_asset_id:row.target_asset_id;const label=id?id.split('/').filter((_,i)=>i!==1).join('/'):up?row.source_reference:row.target_reference;result.set(id||label,{key:id||label,id,label})}return [...result.values()]}
const upstream=computed(()=>neighbors(true)),downstreamNodes=computed(()=>neighbors(false))
function fromDetailToLineage(){if(!detail.value)return;const row=detail.value.object;detailOpen.value=false;tab.value='lineage';selectCenter(row.asset_id,`${row.source}/${row.database}/${row.table}`)}
const gaps=ref<AssetGap[]>([]),gapType=ref(''),gapPage=ref(1),gapTotal=ref(0),gapLoading=ref(false),gapError=ref('')
async function loadGaps(){if(!summary.value)return;const token=++gapToken;gapLoading.value=true;gapError.value='';try{const next=await inventoryApi.gaps({gap:gapType.value,page:gapPage.value,pageSize:20,version:summary.value.version});if(!alive||token!==gapToken)return;gaps.value=next.items;gapTotal.value=next.total}catch(reason){if(alive&&token===gapToken)gapError.value=fail(reason)}finally{if(alive&&token===gapToken)gapLoading.value=false}}
function chooseGap(value:string){gapType.value=value;gapPage.value=1;void loadGaps()}function changeGapPage(value:number){gapPage.value=value;void loadGaps()}
const dictionaryFields:{key:keyof Dictionary;label:string;limit:number}[]=[{key:'businessUse',label:'业务用途',limit:2000},{key:'grain',label:'业务粒度',limit:1000},{key:'businessKey',label:'业务唯一键 / 去重约定',limit:1000},{key:'timeField',label:'业务时间字段',limit:500},{key:'timeMeaning',label:'时间口径 / 时区',limit:1000},{key:'domain',label:'业务主题域',limit:100},{key:'owner',label:'口径负责人',limit:200},{key:'refreshSla',label:'更新约定 / 时效要求',limit:1000}]
const emptyDictionary=():Dictionary=>({businessUse:'',grain:'',businessKey:'',timeField:'',timeMeaning:'',domain:'',owner:'',refreshSla:''})
const editorOpen=ref(false),editor=ref<Dictionary>(emptyDictionary()),savedEditor=ref(''),writeBusy=ref(false),writeError=ref('')
const editorDirty=computed(()=>JSON.stringify(editor.value)!==savedEditor.value)
function editDictionary(){if(!detail.value||!summary.value?.canManageDictionary)return;editor.value={...emptyDictionary(),...(detail.value.dictionaryState.draft??detail.value.dictionaryState.published)};savedEditor.value=JSON.stringify(editor.value);writeError.value='';editorOpen.value=true}
async function saveDictionary(){if(!detail.value||writeBusy.value)return;writeBusy.value=true;writeError.value='';notice.value='';try{const state=await inventoryApi.save({assetId:detail.value.object.asset_id,version:detail.value.version,draftRevision:detail.value.dictionaryState.draftRevision,publishedRevision:detail.value.dictionaryState.publishedRevision,values:editor.value});detail.value.dictionaryState=state;savedEditor.value=JSON.stringify(editor.value);notice.value='字典草稿已保存，尚未改变发布口径'}catch(reason){writeError.value=fail(reason)}finally{writeBusy.value=false}}
async function publishDictionary(){if(!detail.value||writeBusy.value||editorDirty.value)return;writeBusy.value=true;writeError.value='';try{const state=await inventoryApi.publish({assetId:detail.value.object.asset_id,version:detail.value.version,draftRevision:detail.value.dictionaryState.draftRevision,publishedRevision:detail.value.dictionaryState.publishedRevision});detail.value.dictionaryState=state;detail.value.object.dictionary={revision:state.publishedRevision,values:state.published,updatedAt:state.history[0]?.updatedAt??null};editorOpen.value=false;notice.value=`字典修订 ${state.publishedRevision} 已发布，源库结构保持原样`;await loadObjects();if(alive)summary.value=await inventoryApi.summary()}catch(reason){writeError.value=fail(reason)}finally{writeBusy.value=false}}
const objectColumns=[{title:'表 / 视图',key:'name',width:300},{title:'业务用途（人工维护）',key:'business',width:280},{title:'物理结构注释',key:'physical',width:260},{title:'候选分层',key:'layer',width:150},{title:'字段数',dataIndex:'column_count',width:90,align:'right' as const},{title:'治理状态',key:'gap',width:200}]
const fieldColumns=[{title:'字段',dataIndex:'name',width:230},{title:'物理类型',dataIndex:'type',width:180},{title:'物理字段注释',key:'comment',width:300},{title:'可空',key:'nullable',width:150},{title:'声明键',dataIndex:'key',width:90},{title:'分区',key:'partition',width:110}]
const edgeNames:Record<string,string>={etl_static:'ETL源码',live_view_definition:'实库视图定义',datax_config:'DataX配置'}
const edgeColumns=[{title:'上游引用',dataIndex:'source_reference',width:280},{title:'下游引用',dataIndex:'target_reference',width:280},{title:'证据类型',key:'type',width:160},{title:'证据位置',dataIndex:'evidence',width:350},{title:'核验状态',key:'state',width:180}]
const gapColumns=[{title:'对象 / 引用',dataIndex:'asset_id',width:360},{title:'缺口类别',key:'type',width:190},{title:'核对依据',dataIndex:'detail',width:300},{title:'操作',key:'action',width:180}]
const collectionColumns=[{title:'连接',dataIndex:'source',width:150},{title:'库',dataIndex:'database',width:160},{title:'对象数',dataIndex:'object_count',width:100},{title:'结构采集时间',key:'time',width:230},{title:'状态',key:'state',width:200}]
const keyColumns=[{title:'约束',dataIndex:'CONSTRAINT_NAME',width:220},{title:'列',dataIndex:'COLUMN_NAME',width:190},{title:'引用库',dataIndex:'REFERENCED_TABLE_SCHEMA',width:140},{title:'引用表',dataIndex:'REFERENCED_TABLE_NAME',width:240},{title:'引用列',dataIndex:'REFERENCED_COLUMN_NAME',width:190}]
const indexColumns=[{title:'索引',dataIndex:'INDEX_NAME',width:260},{title:'列',dataIndex:'COLUMN_NAME',width:220},{title:'列序',dataIndex:'SEQ_IN_INDEX',width:100},{title:'非唯一（1=是）',dataIndex:'NON_UNIQUE',width:200}]
onMounted(()=>void refresh());onBeforeUnmount(()=>{alive=false;++listToken;++detailToken;++lineageToken;++gapToken;++centerToken})
</script>

